      "resultat_attendu": "Le Total TTC du détail de la facture F-119 est égal au montant TTC de F-119 dans la liste des factures.",
      "verifications": [
        "FAIL if le Total TTC du détail de la facture F-119 est différent du montant TTC de F-119 dans la liste des factures."
      ],
      "releves": [
        {
          "ecran": "detail-facture",
          "vue": "defaut"
        },
        {
          "ecran": "liste-des-factures",
          "vue": "defaut"
        }
      ],
      "regles_calculables": [
